  ytd-engagement-panel-section-list-renderer #contents,
  ytd-comments-header-renderer,
  ytd-multi-page-menu-renderer #sections,
  ytd-multi-page-menu-renderer #items,
  ytd-multi-page-menu-renderer #header,
  ytd-multi-page-menu-renderer #container,
  tp-yt-paper-listbox,
  ytd-simple-menu-header-renderer,
  .yt-sheet-view-model-wiz__content,
  .yt-list-view-model-wiz {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
  }

  ytd-multi-page-menu-renderer ytd-multi-page-menu-section-renderer {
    background-image: var(--liquid-card-gradient) !important;
    border-radius: 14px !important;
    margin: 6px 8px !important;
    padding: 4px !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
  }

  ytd-active-account-header-renderer {
    background-image: var(--liquid-card-gradient) !important;
    border-radius: 14px !important;
    margin: 8px 8px 4px 8px !important;
    padding: 10px 12px !important;
    box-shadow: var(--liquid-3d-rest) !important;
  }

  ytd-menu-service-item-renderer tp-yt-paper-item,
  ytd-menu-navigation-item-renderer tp-yt-paper-item,
  ytd-compact-link-renderer tp-yt-paper-item,
  ytd-compact-link-renderer #endpoint {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    margin: 0 !important;
    min-height: 36px !important;
  }

  ytd-compact-link-renderer,
  ytd-menu-service-item-renderer,
  ytd-menu-navigation-item-renderer,
  ytd-notification-renderer,
  .yt-list-item-view-model-wiz,
  .ytp-menuitem {
    background: transparent !important;
    border-radius: var(--semi-capsule) !important;
    margin: 1px 4px !important;
    min-height: 36px !important;
    box-shadow: none !important;
    transition:
      transform 0.36s var(--silk-spring),
      box-shadow 0.36s var(--silk-spring) !important;
  }

  ytd-compact-link-renderer:hover,
  ytd-menu-service-item-renderer:hover,
  ytd-menu-navigation-item-renderer:hover,
  ytd-notification-renderer:hover,
  .yt-list-item-view-model-wiz:hover,
  .ytp-menuitem:hover {
    background: var(--liquid-item-hover-bg) !important;
    box-shadow: var(--liquid-item-active-rim) !important;
    border-radius: var(--semi-capsule) !important;
    transform: translate3d(-3px, 0, 0) !important;
  }

  /* ONLY Top-Level Comment Threads Get a 3D Floating Card
     (Uses 3-layer dome + 5-stage bevel; skips nested backdrop-filter inside blurred drawers) */
  ytd-item-section-renderer > #contents > ytd-comment-thread-renderer {
    background-image: var(--liquid-card-gradient) !important;
    border-radius: var(--card-radius) !important;
    padding: 12px 16px !important;
    margin-bottom: 12px !important;
    outline: 1px solid transparent !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition:
      transform 0.48s var(--silk-spring),
      box-shadow 0.48s var(--silk-spring) !important;
    box-sizing: border-box !important;
  }

  ytd-item-section-renderer > #contents > ytd-comment-thread-renderer:hover {
    background-image: var(--liquid-card-hover-bg) !important;
    transform: translate3d(0, -3px, 0) !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  ytd-comment-thread-renderer ytd-comment-view-model,
  ytd-comment-thread-renderer ytd-comment-renderer,
  ytd-comment-thread-renderer ytd-comment-replies-renderer,
  ytd-comment-replies-renderer ytd-comment-thread-renderer,
  ytd-comment-replies-renderer ytd-comment-view-model,
  ytd-comment-replies-renderer ytd-comment-renderer,
  ytd-comment-replies-renderer #expander,
  ytd-comment-replies-renderer #expander-contents,
  ytd-comment-replies-renderer #contents,
  ytd-comment-thread-renderer[is-subthread] {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    border: none !important;
    border-radius: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin-bottom: 0 !important;
  }

  ytd-comment-replies-renderer #expander-contents {
    border-left: 2px solid rgba(255, 250, 242, 0.20) !important;
    margin-left: 16px !important;
    padding-left: 14px !important;
    margin-top: 8px !important;
  }

  #footer.ytd-engagement-panel-section-list-renderer {
    background: rgba(12, 13, 16, 0.68) !important;
    padding: 10px 14px !important;
    border-top: 1px solid rgba(255, 250, 242, 0.12) !important;
    box-shadow: none !important;
  }

  #simplebox-placeholder.ytd-comment-simplebox-renderer,
  #placeholder-area.ytd-comment-simplebox-renderer {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    padding: 0 !important;
  }

  ytd-comment-simplebox-renderer,
  #main.ytd-commentbox {
    background-color: rgba(20, 21, 26, 0.45) !important;
    background-image: var(--liquid-card-gradient) !important;
    border-radius: var(--semi-capsule) !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
    padding: 10px 14px !important;
    transition: box-shadow 0.42s var(--silk-spring), transform 0.42s var(--silk-spring) !important;
  }

  ytd-comment-simplebox-renderer:hover,
  #main.ytd-commentbox:focus-within {
    background-image: var(--liquid-card-hover-bg) !important;
    transform: translate3d(0, -2px, 0) !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  /* --- 10. WATCH PAGE, PLAYER & iOS LIQUID GLASS ACTION PILLS --- */
  .html5-video-player:not(.ytp-fullscreen) {
    border-radius: var(--panel-radius) !important;
    box-shadow:
      var(--liquid-popup-depth),
      0 0 38px rgba(255, 25, 25, 0.14) !important;
    overflow: hidden !important;
  }

  .html5-video-player.ytp-fullscreen,
  ytd-watch-flexy[theater] .html5-video-player {
    border-radius: 0 !important;
    box-shadow: none !important;
  }

  #description.ytd-watch-metadata,
  ytd-playlist-panel-renderer #container.ytd-playlist-panel-renderer,
  ytd-live-chat-frame,
  ytd-clarification-renderer,
  ytd-info-panel-content-renderer {
    background: var(--liquid-card-gradient) !important;
    backdrop-filter: var(--liquid-blur) !important;
    -webkit-backdrop-filter: var(--liquid-blur) !important;
    border-radius: var(--panel-radius) !important;
    border: none !important;
    outline: 1px solid transparent !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition:
      transform 0.55s var(--silk-spring),
      box-shadow 0.55s var(--silk-spring) !important;
  }

  /* Unmask inner playlist queue items so they don't clash with the glass container */
  ytd-playlist-panel-renderer #header-contents,
  ytd-playlist-panel-renderer .playlist-items,
  ytd-playlist-panel-video-renderer {
    background: transparent !important;
    background-color: transparent !important;
  }

  ytd-playlist-panel-video-renderer:hover,
  ytd-playlist-panel-video-renderer[selected] {
    background: var(--liquid-item-hover-bg) !important;
    box-shadow: var(--liquid-item-active-rim) !important;
    border-radius: var(--card-radius) !important;
  }

  #description.ytd-watch-metadata:hover,
  ytd-playlist-panel-renderer #container.ytd-playlist-panel-renderer:hover,
  ytd-live-chat-frame:hover {
    background: var(--liquid-card-hover-bg) !important;
    transform: translate3d(0, -3px, 0) !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  /* Watch Page Action Pills (Share, Ask, Save, Download, 3-Dot) */
  .yt-spec-button-shape-next--tonal,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  ytd-watch-metadata #actions yt-button-view-model .yt-spec-button-shape-next,
  ytd-watch-metadata #actions ytd-button-renderer .yt-spec-button-shape-next,
  ytd-watch-metadata #actions ytd-download-button-renderer .yt-spec-button-shape-next,
  ytd-watch-metadata #actions #button-shape.ytd-menu-renderer button {
    background-color: rgba(26, 27, 34, 0.44) !important;
    background-image: var(--liquid-card-gradient) !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border: none !important;
    border-radius: var(--semi-capsule) !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition:
      transform 0.42s var(--silk-spring),
      box-shadow 0.42s var(--silk-spring) !important;
  }

  .yt-spec-button-shape-next--tonal:hover,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal:hover,
  ytd-watch-metadata #actions yt-button-view-model .yt-spec-button-shape-next:hover,
  ytd-watch-metadata #actions ytd-button-renderer .yt-spec-button-shape-next:hover,
  ytd-watch-metadata #actions ytd-download-button-renderer .yt-spec-button-shape-next:hover,
  ytd-watch-metadata #actions #button-shape.ytd-menu-renderer button:hover {
    background-image: var(--liquid-card-hover-bg) !important;
    box-shadow: var(--liquid-3d-hover) !important;
    transform: translate3d(0, -2.5px, 0) scale3d(1.03, 1.03, 1) !important;
  }

  ytd-comment-thread-renderer .yt-spec-button-shape-next--tonal,
  ytd-comment-thread-renderer .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  ytd-browse-feed-actions-renderer .yt-spec-button-shape-next--tonal,
  ytd-browse-feed-actions-renderer .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  ytd-rich-item-renderer #menu button {
    background: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    box-shadow: none !important;
  }

  ytd-browse-feed-actions-renderer .yt-spec-button-shape-next:hover {
    background: var(--liquid-item-hover-bg) !important;
    box-shadow: var(--liquid-item-active-rim) !important;
  }

  /* Unified Segmented Like | Dislike Liquid Glass Capsule */
  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper {
    background-color: rgba(26, 27, 34, 0.44) !important;
    background-image: var(--liquid-card-gradient) !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border-radius: var(--semi-capsule) !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition: transform 0.42s var(--silk-spring), box-shadow 0.42s var(--silk-spring) !important;
    overflow: hidden !important;
  }

  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper:hover {
    background-image: var(--liquid-card-hover-bg) !important;
    transform: translate3d(0, -2.5px, 0) scale3d(1.02, 1.02, 1) !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  /* HIGH-SPECIFICITY OVERRIDE: Prevents inner Like & Dislike buttons from double-carding inside #actions */
  ytd-watch-metadata #actions .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next,
  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next,
  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next--tonal,
  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    transform: none !important;
  }

  ytd-watch-metadata #actions .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next:hover,
  .ytSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper .yt-spec-button-shape-next:hover {
    background: rgba(255, 250, 242, 0.14) !important;
    background-image: none !important;
    box-shadow: none !important;
    transform: none !important;
  }

  #submit-button.ytd-commentbox yt-button-shape button,
  ytd-button-renderer.style-primary yt-button-shape button {
    background: #ff0000 !important;
    color: #ffffff !important;
    border-radius: var(--semi-capsule) !important;
    box-shadow: var(--liquid-3d-rest) !important;
  }

  .ytp-play-progress,
  .ytp-swatch-background-color,
  ytd-thumbnail-overlay-resume-playback-renderer #progress,
  .yt-spec-icon-badge-shape--type-notification .yt-spec-icon-badge-shape__badge {
    background: #ff0000 !important;
  }

  /* --- 11. YOUTUBE MUSIC & SCROLLBARS --- */
  ytmusic-app-layout[player-visible_] > [slot=player-bar],
  #player-bar-background.ytmusic-app-layout,
  #nav-bar-background.ytmusic-app-layout {
    background: var(--liquid-popup-gradient) !important;
    backdrop-filter: var(--liquid-blur) !important;
    -webkit-backdrop-filter: var(--liquid-blur) !important;
    box-shadow: var(--liquid-popup-depth) !important;
    border: none !important;
  }

  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(255, 250, 242, 0.14), rgba(255, 238, 212, 0.38));
    border-radius: 9999px;
  }
}
